import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/commands.md","filePath":"modules/storage/commands.md","lastUpdated":0}`),a={name:`modules/storage/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiStorage 的命令, 权限节点和常见报错列在下面, 可以照着表直接执行</p><p>EmakiStorage 的主命令是 <code>/emakistorage</code>, 别名为 <code>/estorage</code>. 文档示例统一使用 <code>/estorage</code></p><p>这些命令不是在 <code>paper-plugin.yml</code> 里声明的, 而是插件启动时通过 CoreLib 注册的, 所以别名只有 <code>/estorage</code> 一个; <code>config.yml</code> 注释里出现的 <code>/storage</code> 是旧写法, 不会被注册</p><p>你直接执行 <code>/estorage</code> (不带参数) 就会打开自己的仓库, 需要 <code>emakistorage.use</code> 权限 (<code>emakistorage.admin</code> 也可以). 管理类子命令都要求 <code>emakistorage.admin</code>; <code>reload</code> 和 <code>debug</code> 另外各有专用权限, 但 <code>emakistorage.admin</code> 也能代替</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/estorage</code></td><td><code>emakistorage.use</code></td><td>打开自己的仓库. 只有玩家能执行</td></tr><tr><td><code>/estorage help</code></td><td><code>emakistorage.use</code></td><td>显示帮助. 整条命令受命令级权限约束, help 分支自己不再额外检查权限, 但仍需要这个权限</td></tr><tr><td><code>/estorage open &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>用管理员身份打开目标玩家的仓库. 执行命令的人必须是玩家</td></tr><tr><td><code>/estorage slot grant &lt;player&gt; &lt;amount&gt;</code></td><td><code>emakistorage.admin</code></td><td>调整目标玩家的授予槽位数. <code>amount</code> 写负数表示回收槽位</td></tr><tr><td><code>/estorage stacklimit player &lt;player&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>设置目标玩家的玩家级单槽上限</td></tr><tr><td><code>/estorage stacklimit slot &lt;player&gt; &lt;slot&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>设置目标玩家某个逻辑槽位的条目级上限</td></tr><tr><td><code>/estorage info &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>打印容量是怎么算出来的, 以及页数, <code>stackLimit</code>, 排序模式与总量</td></tr><tr><td><code>/estorage export &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>把仓库导出成可读的 YAML, 写到 <code>exports/export-&lt;uuid&gt;.yml</code></td></tr><tr><td><code>/estorage autopickup [on|off|toggle]</code></td><td><code>emakistorage.autopickup</code></td><td>管理自己的自动拾取开关. <code>on</code> (等价于 <code>true</code> / <code>enable</code>) 表示开启; <code>off</code> (等价于 <code>false</code> / <code>disable</code>) 表示关闭; 不写参数或写其他值都按切换处理. 还需要 <code>auto_pickup.enabled: true</code>, 否则会回报未启用</td></tr><tr><td><code>/estorage reload</code></td><td><code>emakistorage.reload</code> 或 <code>emakistorage.admin</code></td><td>重载配置, 语言和 GUI 模板, 并回报已加载的模板数量</td></tr><tr><td><code>/estorage debug ...</code></td><td><code>emakistorage.debug</code> 或 <code>emakistorage.admin</code></td><td>管理 debug 模块. 可用的模块是 <code>storage</code> 与 <code>chat_input</code>, 具体子命令由 CoreLib 的 DebugCommand 提供</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/estorage</span></span>
<span class="line"><span>/estorage help</span></span>
<span class="line"><span>/estorage open Steve</span></span>
<span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage slot grant Steve -5</span></span>
<span class="line"><span>/estorage stacklimit player Steve 100000</span></span>
<span class="line"><span>/estorage stacklimit player Steve max</span></span>
<span class="line"><span>/estorage stacklimit player Steve 10k</span></span>
<span class="line"><span>/estorage stacklimit slot Steve 3 5000</span></span>
<span class="line"><span>/estorage info Steve</span></span>
<span class="line"><span>/estorage export Steve</span></span>
<span class="line"><span>/estorage autopickup on</span></span>
<span class="line"><span>/estorage autopickup</span></span>
<span class="line"><span>/estorage reload</span></span>
<span class="line"><span>/estorage debug storage on</span></span></code></pre></div><h2 id="参数写法" tabindex="-1">参数写法 <a class="header-anchor" href="#参数写法" aria-label="Permalink to “参数写法”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>接受的写法</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;amount&gt;</code> (slot grant)</td><td>十进制整数, 可为负</td><td>写负数表示回收授予槽位</td></tr><tr><td><code>&lt;limit&gt;</code> (stacklimit)</td><td>十进制数字, 紧凑单位 (<code>k</code> <code>m</code> <code>b</code> <code>t</code> <code>p</code> <code>e</code>), <code>max</code>, <code>0</code></td><td><code>max</code> 会解析成 <code>Long.MAX_VALUE</code>. <code>0</code> 是明确表示&quot;恢复继承&quot;的写法: 条目级填 <code>0</code> 会落回玩家级, 玩家级填 <code>0</code> 会落回 <code>capacity.default_stack_limit</code>. 其余解析结果只要 <code>&lt;= 0</code> 或者溢出, 都会直接拒绝, 不会截断, 免得手误之后不报错地变成另一个上限</td></tr><tr><td><code>&lt;slot&gt;</code></td><td>逻辑槽位索引 (0 起)</td><td>这个槽位没有条目时, 命令会回报&quot;槽位为空&quot;, 不会新建条目</td></tr></tbody></table><h2 id="写操作要求目标玩家在线" tabindex="-1">写操作要求目标玩家在线 <a class="header-anchor" href="#写操作要求目标玩家在线" aria-label="Permalink to “写操作要求目标玩家在线”">​</a></h2><p>为什么要求在线: <code>slot grant</code> 和 <code>stacklimit</code> 这两类会改数据的操作, 在目标玩家离线时会直接拒绝, 回报 <code>command.target_offline</code>. 原因是它们要改的是已经载入内存的仓库对象: 如果直接去改一个还没载入的存档, 会和该玩家下次登录时的载入过程撞在一起, 可能把改动覆盖掉或丢掉</p><p>注意线程: 针对在线玩家的改数据操作会交给该玩家自己所在区域的线程执行, 不是执行命令的人所在的那个线程. 如果这时该玩家的仓库数据还在载入, 命令会回报 <code>general.data_loading</code>, 请稍后再试</p><p>只读命令没有这个限制: <code>info</code> 和 <code>export</code> 走的是快照读取, 需要时可以从磁盘载入数据, 所以对离线玩家也能用. <code>open &lt;player&gt;</code> 也支持离线玩家</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>emakistorage.use</code></td><td><code>true</code></td><td>打开自己的仓库</td></tr><tr><td><code>emakistorage.unlock.purchase</code></td><td><code>true</code></td><td>在 GUI 里使用付费扩容. 还需要 <code>unlock.purchase_enabled: true</code></td></tr><tr><td><code>emakistorage.autopickup</code></td><td><code>true</code></td><td>使用 <code>/estorage autopickup</code> 命令和自动拾取功能</td></tr><tr><td><code>emakistorage.reload</code></td><td><code>op</code></td><td>使用 <code>/estorage reload</code>. 可被 <code>emakistorage.admin</code> 代替</td></tr><tr><td><code>emakistorage.debug</code></td><td><code>op</code></td><td>使用 <code>/estorage debug ...</code>. 可被 <code>emakistorage.admin</code> 代替</td></tr><tr><td><code>emakistorage.admin</code></td><td><code>op</code></td><td>使用 <code>open</code>, <code>slot</code>, <code>stacklimit</code>, <code>info</code>, <code>export</code>, 并可代替 reload/debug 专用权限</td></tr></tbody></table><h2 id="数值档位权限" tabindex="-1">数值档位权限 <a class="header-anchor" href="#数值档位权限" aria-label="Permalink to “数值档位权限”">​</a></h2><p>想给某些玩家更多槽位或更高上限, 用下面这两个<strong>数值档位</strong>权限即可; 它们不在 <code>paper-plugin.yml</code> 里声明, 直接授予带数字后缀的节点</p><table tabindex="0"><thead><tr><th>权限前缀</th><th>作用</th><th>取值规则</th></tr></thead><tbody><tr><td><code>emakistorage.slots.&lt;n&gt;</code></td><td>追加 <code>n</code> 个槽位</td><td>扫描玩家所有生效的权限, 取数字后缀的<strong>最大值</strong>, 不累加</td></tr><tr><td><code>emakistorage.stacklimit.&lt;n&gt;</code></td><td>提供玩家级单槽上限 <code>n</code></td><td>同样取最大值</td></tr></tbody></table><p>注意: 两者都<strong>不支持通配</strong>, 写成 <code>emakistorage.slots.*</code> 这种样子会被跳过. 有些权限插件会把通配展开成&quot;持有每一个 n&quot;, 那样就会把玩家悄悄推到最高档; 所以实现只接受纯数字后缀, 后缀里有 <code>.</code> 或不是数字的一律忽略</p><p>常见 LuckPerms 示例:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/lp group default permission set emakistorage.use true</span></span>
<span class="line"><span>/lp group default permission set emakistorage.unlock.purchase true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.slots.100 true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.stacklimit.100000 true</span></span>
<span class="line"><span>/lp group admin permission set emakistorage.admin true</span></span></code></pre></div><h2 id="reload-行为" tabindex="-1">reload 行为 <a class="header-anchor" href="#reload-行为" aria-label="Permalink to “reload 行为”">​</a></h2><p>执行 <code>/estorage reload</code> 时, 插件会依次做这几件事:</p><ol><li>释放缺失的默认资源, 受 <code>config.yml &gt; release_default_data</code> 控制</li><li>重新读取 <code>config.yml</code>, <code>lang/*.yml</code>, <code>unlock_costs.yml</code> 与 <code>gui/storage_gui.yml</code></li><li>按新的 <code>gui.storage_rows</code> 重新换算 GUI 布局</li><li>清理过期流水日志, 并回报已加载的界面模板数量</li></ol><p>怎么判断重载真的生效了: 重载会先过 CoreLib 的配置预检, 预检没过 (比如 <code>config.yml</code> 或 <code>gui/</code> 缺失, 预检服务不可用) 时整次重载会被回滚, 旧配置照旧生效, 控制台会输出预检报告. 这时命令却仍会打印&quot;重载成功&quot;的摘要, 所以到底有没有真正生效, 要看控制台的预检输出和配置键</p><p>改完记得看一眼: <code>gui.storage_rows</code> 超出 1–5 时会被收回到范围内, 并在控制台记 warning, 见 <a href="./configuration.html">配置详解</a></p><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to “常见失败原因”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td><code>找不到玩家</code></td><td>玩家名对不上, 而且服务器的缓存里也没有这个离线玩家</td></tr><tr><td><code>玩家 ... 当前离线, 无法执行该写操作</code></td><td><code>slot grant</code> / <code>stacklimit</code> 的目标玩家必须在线</td></tr><tr><td><code>仓库数据仍在加载, 请稍后再试</code></td><td>目标玩家在线, 但他的仓库还没载入完成</td></tr><tr><td><code>槽位为空</code></td><td><code>stacklimit slot</code> 指定的那个逻辑槽位上现在没有条目</td></tr><tr><td><code>stacklimit</code> 参数被拒绝</td><td>解析结果 <code>&lt;= 0</code> (<code>0</code> 本身除外) 或者超出 <code>long</code> 的范围. 请用正整数, 紧凑单位, <code>max</code> 或 <code>0</code></td></tr><tr><td><code>仓库界面打开失败</code></td><td>GUI 模板没加载或者解析失败, 去看控制台的 warning</td></tr></tbody></table>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};